def solve(s: str) -> bool:
    pairs = {')':'(', ']':'[', '}':'{'}
    stack = []
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

