def solve(s: str) -> bool:
    """Return True if brackets in string s are balanced and properly nested.
    Supports parentheses (), square brackets [], and curly braces {}.
    Other characters are ignored.
    """
    opening = {'(': ')', '[': ']', '{': '}'}
    closing = {')', ']', '}'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(opening[ch])
        elif ch in closing:
            if not stack or stack[-1] != ch:
                return False
            stack.pop()
    return not stack

