def solve(grid):
    """Count the number of islands (4-directionally connected land cells).
    The grid may be jagged (rows of different lengths) and may contain integers, strings
    or booleans representing land. Any value equal to 1, the string '1', True, or any
    non‑zero integer is treated as land.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    def is_land(v):
        # treat 1, '1', True, or any non‑zero int as land
        if v == 1 or v == '1' or v is True:
            return True
        return isinstance(v, int) and v != 0
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < len(grid[nx]):
                    if (nx, ny) not in visited and is_land(grid[nx][ny]):
                        stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if is_land(grid[i][j]) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

