    # Make deep copies of the inner intervals to avoid modifying the caller's data
    copies = [list(it) for it in intervals]
    copies.sort(key=lambda x: x[0])
    merged = []
    for s, e in copies:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            merged[-1][1] = max(merged[-1][1], e)
    return merged"
