def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting / binary search for O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find location to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

