def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find insertion point (first >= x) for strictly increasing, use bisect_left
        # but need strictly increasing, so we replace first >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

