def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings or ints. Supports +, -, *, / with truncation toward zero.
    """
    stack = []
    for tok in tokens:
        # Allow integer tokens as int type
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncates toward zero
                # Use int division with truncation toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # token may be string representation of int or int already
            if isinstance(tok, int):
                stack.append(tok)
            else:
                stack.append(int(tok))
    return stack[0] if stack else 0

